function PlayerComponent:__init()
    ECSComponent.__init(self)
    self.name = "PlayerComponent"
    ---@type PlayerDojo
    self.playerDojo = PlayerDojo.New()

    ---@type CardStarGiftDojo
    self._cardStarGiftsDojo = CardStarGiftDojo.New()

    self.__rewardsDialogInfo = {}
    self.__functionUnlockDialogDataInfo = {}

    ---@type Engine.Modules.CDTimerModule @ @ 玩家头像、头像框、徽章，倒计时map（key：道具id，value：计时器）
    self.playerHeadUpdateTimer_ = CfUtils.CDTimerAppend(1, CountDownTime, false, true, Bind(self, self.OnPlayerHeadTimerUpdateHandler_))

    self.progressInfo = {}
    self.randomTime = 0
    self.isStartedTcp = false

    ---@type GlobalTalentMgr
    GlobalTalentMgr = import('Game.GlobalTalent.GlobalTalentMgr')
end

function PlayerComponent:__delete()
    self.isStartedTcp = false
    self:StopRewardsSpecialDialogCo()
    self.randomTime = nil
    self.name = nil
    self.playerDojo = nil
    self._cardStarGiftsDojo = nil

    --新加战队信息
    self.fightcards = nil

    self.progressInfo = nil
    self.__rewardsDialogInfo = nil
    self.__functionUnlockDialogDataInfo = nil

    if isNotNull(self.playerHeadUpdateTimer_) then
        CfUtils.CDTimerRemove(self.playerHeadUpdateTimer_)
        self.playerHeadUpdateTimer_ = nil
    end

    if GlobalTalentMgr then
        GlobalTalentMgr:GetInstance():Delete()
        GlobalTalentMgr = nil
    end
end

---@param dojo CardStarGiftDojo
