---IsOpenByLevel
---色彩等级是否解锁
---@param openLevel number
function PlayerComponent:IsOpenByLevel(openLevel)
    return checkNumber(self.playerDojo.level) >= checkNumber(openLevel)
end

function PlayerComponent:__ShowWaterMark()
    local trans = UIModule.RootCanvas.transform.parent.transform
    local wmGo = trans:Find("UIWaterMark")
    if not wmGo then
        local loader = CS.Engine.Modules.ResourceModule.LoadBundleSync('Prefabs/UIWaterMark.prefab', nil, true)
        if loader and loader.IsSuccess then
            wmGo = loader:Instantiate(trans, false)
            wmGo.name = "UIWaterMark"
            kTool.SetActive(wmGo, true)
            wmGo.gameObject:GetComponent(typeof(CS.UnityEngine.Canvas)).renderMode = CS.UnityEngine.RenderMode.ScreenSpaceOverlay
            local t = wmGo:GetComponent(typeof(CS.UnityEngine.RectTransform))
            t.anchorMin = Vector2.zero
            t.anchorMax = Vector2.one
            t.offsetMin = Vector2.zero
            t.offsetMax = Vector2.zero
            t.localPosition = Vector3.zero
            t.localRotation = Quaternion.identity
            t.localScale = Vector3.one
            wmGo.layer = trans.gameObject.layer
        end
        loader:Release()
    else
        kTool.SetActive(wmGo, true)
    end

    if wmGo then
        ---@type UIWaterMark
        local wmGoEnv = CfUtils.GetLuaScr(wmGo, "Game.Main.UIWaterMark")
        if wmGoEnv then
            wmGoEnv:SetPlayerId(self.playerDojo.playerId)
        end
    end
end

