function PlayerComponent:CheckPlayerSignInBox()
    local playerDojo = self:GetPlayerDojo()
    local dailySignIn = playerDojo.dailySignIn
    local treasureDays = checkInt(dailySignIn.treasureDays)
    local treasureDrawIds = dailySignIn.treasureDrawIds
    local treasureRewards = dailySignIn.treasureRewards
    local isCanDraw = false
    for k, v in pairs(treasureRewards) do
        if treasureDays >= checkInt(v.times) then
            local isHaveDraw = false 
            for index , id  in pairs(treasureDrawIds) do
                if checkInt(id) == checkInt(v.id) then
                    isHaveDraw = true 
                    break
                end
            end
            if not isHaveDraw then
                isCanDraw = true   
                break  
            end            
        end
    end
    if isCanDraw then
        GameUtils.SetRedPointNum(Constants.RedPointConst.PlayerSignIn , 1)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.PlayerSignIn)
    else 
        GameUtils.SetRedPointNum(Constants.RedPointConst.PlayerSignIn , 0)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.PlayerSignIn)
    end
end
function PlayerComponent:InitPrivilegeCards(privilegeCards)
    local currentTime = os.time()
    for i, v in pairs(privilegeCards) do
        v.lastTime = currentTime
    end
    self.playerDojo.privilegeCards = privilegeCards
end
function PlayerComponent:GetPrivilegeCardById(id)
    id = checkInt(id)
    local privilegeCard = {}
    for i, v in pairs(self:GetPlayerDojo().privilegeCards) do
        if id == v.privilegeCardId then
            privilegeCard = v
            break
        end
    end
    return privilegeCard
end
function PlayerComponent:GetPrivilegeCardSecondsById(id)
    local privilegeCard = self:GetPrivilegeCardById(id)
    if privilegeCard.lastTime then
        local remainSeconds = privilegeCard.remainSeconds - (os.time() - privilegeCard.lastTime)
        if remainSeconds < 0 then
            return 0
        else
            return remainSeconds
        end
    end
    return privilegeCard.remainSeconds or 0
end

function PlayerComponent:GetPrivilegeCards()
    return self:GetPlayerDojo().privilegeCards
end

---UpdateGoodsNo
---
---@param id number
---@param addV number
function PlayerComponent:UpdateGoodsNo(id, addV)
    local checkNumber = checkNumber
    id = checkNumber(id)
    if id == Constants.Currency.GoldId then
        self.playerDojo.gold = checkNumber(self.playerDojo.gold) + checkNumber(addV)
    elseif id == Constants.Currency.PayDiamondId then
        self.playerDojo.diamond = checkNumber(self.playerDojo.diamond) + checkNumber(addV)
    elseif id == Constants.Currency.FreeDiamondId then
        self.playerDojo.freeDiamond = checkNumber(self.playerDojo.freeDiamond) + checkNumber(addV)
    elseif id == Constants.Currency.HpId then
        self.playerDojo.hp = checkNumber(self.playerDojo.hp) + checkNumber(addV)
        AppService:GetInstance():UpdateRecoveryValue(self.playerDojo.hp)
    elseif id == Constants.Currency.LadderTicket then
        self.playerDojo.ladderTicketNums = checkNumber(self.playerDojo.ladderTicketNums) + checkNumber(addV)
    elseif id == Constants.Currency.LadderCoin then
        self.playerDojo.ladderCoin = checkNumber(self.playerDojo.ladderCoin) + checkNumber(addV)
    elseif id == Constants.Currency.WorldBossCoin then
        self.playerDojo.worldBossCoin = checkNumber(self.playerDojo.worldBossCoin) + checkNumber(addV)
    elseif id == Constants.Currency.LadderStruggleCurrency then
        self.playerDojo.asyncCoin = checkNumber(self.playerDojo.asyncCoin) + checkNumber(addV)
    elseif id == Constants.Currency.LadderStruggleTicket then
        self.playerDojo.asyncRecoverTicket = checkNumber(self.playerDojo.asyncRecoverTicket) + checkNumber(addV)
    elseif id == Constants.Currency.LadderStruggleSingleCurrency then
        self.playerDojo.asyncCoin = checkNumber(self.playerDojo.asyncCoin) + checkNumber(addV)
    elseif id == Constants.Currency.LadderStruggleSingleTicket then
        self.playerDojo.asyncSingleRecoverTicket = checkNumber(self.playerDojo.asyncSingleRecoverTicket) + checkNumber(addV)
    elseif id == Constants.Currency.CartCatTicket then
        self.playerDojo.catCarCoin = checkNumber(self.playerDojo.catCarCoin) + checkNumber(addV)
    elseif id == Constants.Currency.CumulativeScore then
        --self.playerDojo.payCumulative = checkNumber(self.playerDojo.payCumulative) + checkNumber(addV)
        ---充值积分特殊处理，只在充值的时候更新，其他道具领取时不做任何处理
        self.playerDojo.payCumulative = checkNumber(self.playerDojo.payCumulative)
    elseif id == Constants.Currency.TipCoin then
        self.playerDojo.tipCoin = checkNumber(self.playerDojo.tipCoin) + checkNumber(addV)
    elseif id == Constants.Currency.ClubCoin then
        self.playerDojo.clubCoin = checkNumber(self.playerDojo.clubCoin) + checkNumber(addV)
    elseif id == Constants.Currency.CatBallTicket then
        self.playerDojo.catBallTicket = checkNumber(self.playerDojo.catBallTicket) + checkNumber(addV)
    elseif id == Constants.Currency.TowerTicket then
        self.playerDojo.towerTicket = checkNumber(self.playerDojo.towerTicket) + checkNumber(addV)
    elseif id == Constants.Currency.ClubFeedCatSkinCoin then
        self.playerDojo.clubFeedCatSkinCoin = checkNumber(self.playerDojo.clubFeedCatSkinCoin) + checkNumber(addV)
    elseif id == Constants.Currency.LightDarkCoin then
        self.playerDojo.lightDarkCoin = checkNumber(self.playerDojo.lightDarkCoin) + checkNumber(addV)
    elseif id == Constants.Currency.BattleCardGameCoin then
        self.playerDojo.stardustCoin = checkNumber(self.playerDojo.stardustCoin) + checkNumber(addV)
    elseif id == Constants.Currency.StoreSkinTicket then
        self.playerDojo.skinTicket = checkNumber(self.playerDojo.skinTicket) + checkNumber(addV)
    else
        if isSet(self.playerDojo.currency, tostring(id)) then
            local num = checkNumber(self.playerDojo.currency[tostring(id)])
            self.playerDojo.currency[tostring(id)] = num + checkNumber(addV)
        end
    end
    Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, checkNumber(id))
end

