-- AF
function PlayerComponent:AFUploadLevel(oneLevel)
    local uploadLevels = { 1, 5, 10 ,22, 30 , 42 , 45 , 60 ,75}
    oneLevel = checkInt(oneLevel)
    for i, level in pairs(uploadLevels) do
        if checkInt(level) == oneLevel then
            xRecord.af_internal(string.format("level_%s", oneLevel), { playerId = tostring(self.playerDojo.playerId) })
            break
        end
    end
end
---UpdateMainExp
---更新主角经验
---@param lv number 主角等级
---@param exp number 主角经验
---@param hp number 主角体力
---@param isShowTip boolean nil 默认为true
function PlayerComponent:UpdatePlayerLvMainExp(lv, exp, hp, isShowTip)
    ---处理升级事件的逻辑,是否提示已升级等
    local oldLevel = checkInt(self.playerDojo.level)
    local newLevel = checkInt(lv)
    self.expBefore = DeepCopy(self.playerDojo.mainExp)
    self.playerDojo.mainExp = checkInt(exp)
    isShowTip = isNull(isShowTip) or isShowTip
    if isShowTip then
        self:ShowExpChangeTips({
            oldLevel = oldLevel,
            nowLevel = newLevel,
            oldExp = checkNumber(self.expBefore),
            nowExp = self.playerDojo.mainExp
        })
    end
    hp = tonumber(hp)
    if (not isNull(hp)) and hp >= 0 then
        self.playerDojo.hp = checkNumber(hp)
        AppService:GetInstance():UpdateRecoveryValue(self.playerDojo.hp)
    end
    if oldLevel >= 0 and (newLevel > oldLevel) then
        self.playerDojo.level = newLevel
        ---@type WhiteLevelGiftComponent
        local whiteLevelGiftComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.WhiteLevelGiftComponent)
        if whiteLevelGiftComponent then
            whiteLevelGiftComponent:SetPlayerLevel(newLevel)
        end
        self:AFUploadLevel(newLevel)
        xRecord.setUserPlayer({ playerLevel = tostring(newLevel) })
        --- 玩家升级打点记录
        ---
        ---已升级
        local expInfo = CardConfMgr:GetInstance():GetPlayerExpByLevelId(newLevel, oldLevel)
        self.playerDojo.hpLimit = checkInt(expInfo.hpMax) + checkNumber(GameUtils.GetPrivilegeCardAddNumByRefId(1, "ApMax"))
        if #expInfo.rewards > 0 then
            local rewards = {}
            for _, reward in pairs(expInfo.rewards) do
                if checkNumber(reward.goodsId) ~= Constants.Currency.HpId then
                    table.insert(rewards, reward)
                end
            end
            if #rewards > 0 then
                ---新的逻辑，服务器只返回最新的hp值，如果奖励中配这个值也不再添加
                GoodsUtils.DrawRewards(rewards)
            end
        end
        ----体力上限值的恢复值也要修改下
        AppService:GetInstance():UpdateRecoveryValueMax(self.playerDojo.hpLimit)
        ---插入升级弹窗数据
        self:InsertUpgradeDialogData(oldLevel, newLevel)
        ---修正卡牌等级
        ---@type CardComponent
        local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        cardComp:FixCardLevel(oldLevel, newLevel)

        x_record_event(string.format('LEVEL_UP_%d', checkInt(newLevel)))
        --玩家升级
        local SDKService = import('Game.Entry.SDKService')
        SDKService:UpgradedRole()
        return true
    end
    return false
end

--获取更新主角经验之前的主角经验
function PlayerComponent:GetExpBefore()
    if isNull(self.expBefore) then
        --没用设置的话就返回当前的
        return self.playerDojo.mainExp
    end
    return self.expBefore
end

