---更新头像头像框贴纸道具的信息
---@param rewards table @ 服务端返回的rewards其中的一项
function PlayerComponent:UpdateAvatarFramePasterGoods(reward)
    if type(reward) ~= 'table' then
        return
    end
    local headAvatarVo = PlayerInfoUtils.GetHeadAvatarVo(reward.goodsId)
    if headAvatarVo == nil then
        return
    end
    local type = headAvatarVo.kind--区分是头像头像框还是贴纸
    if isNull(self.playerDojo.playerOtherInfo[tostring(type)]) then
        self.playerDojo.playerOtherInfo[tostring(type)] = {}
    end
    if reward.convertGoods == nil or next(reward.convertGoods) == nil then
        self.playerDojo.playerOtherInfo[tostring(type)][tostring(reward.goodsId)] = reward
        PlayerInfoUtils.UpdateAvatarNewStateById(reward.goodsId, true)
    end
end

