---ShowRewardsSpecialDialog
---显示奖励指定弹窗
function PlayerComponent:ShowRewardsSpecialDialog(callBack, autoClose)
    self:StopRewardsSpecialDialogCo(true)
    if next(self.__rewardsDialogInfo) == nil then
        return
    end
    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    blocker:AddCondition("ShowRewardsSpecialDialog")

    local cs_coroutine = require 'XLua.cs_coroutine'
    local CheckIsShowDialogByIdMap = GameUtils.CheckIsShowDialogByIdMap
    self.RewardDialogCo = cs_coroutine.start(function()
        blocker:RemoveCondition("ShowRewardsSpecialDialog")
        local values = table.values(Constants.RewardDialogType)
        table.sort(values)

        local yield_return = cs_coroutine.yield_return
        for i, dialogType in ipairs(values) do
            local dialogData = self.__rewardsDialogInfo[dialogType]

            if dialogData and next(dialogData) then
                if autoClose then
                    dialogData.parameters.autoClose = true
                end
                yield_return(UIModule.OpenDialog(dialogData))
                --- 如果该界面没关闭的话 则等待它关闭
                while CheckIsShowDialogByIdMap({ [dialogData.id] = true }) do
                    yield_return()
                end
            end
        end

        self:ShowFunctionUnlockDialog(Constants.CommonUnlockType.PassQuest)

        --- 清理缓存
        self.__rewardsDialogInfo = {}
        self.RewardDialogCo = nil
        if callBack then
            callBack()
        end
    end)

    return self.RewardDialogCo
end
function PlayerComponent:StopRewardsSpecialDialogCo(isDisableClear)
    if self.RewardDialogCo then
        local cs_coroutine = require 'XLua.cs_coroutine'
        cs_coroutine.stop(self.RewardDialogCo)
        self.RewardDialogCo = nil
        if not isDisableClear then
            self.__rewardsDialogInfo = {}
        end
    end
end

function PlayerComponent:ClearRewardsDialogInfoByType(type)
    self.__rewardsDialogInfo[type] = nil
end

function PlayerComponent:StopMainChapterExtraDialog()
    if self.mainChapterExtraDialogCo then
        local cs_coroutine = require 'XLua.cs_coroutine'
        cs_coroutine.stop(self.mainChapterExtraDialogCo)
        self.mainChapterExtraDialogCo = nil
    end
end

function PlayerComponent:ShowMainChapterExtraDialog(unlockType)
    self:StopMainChapterExtraDialog()
    if next(self.__functionUnlockDialogDataInfo) == nil or not self.isShowTeamRatingDialog then
        return
    end
    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    blocker:AddCondition("ShowMainChapterExtraDialog")

    local UIModule = CS.Engine.UI.UIModule
    local Yielders = CS.Engine.Lib.Yielders
    local sce = 0.3
    local cs_coroutine = require 'XLua.cs_coroutine'
    local CheckIsShowDialogByIdMap = GameUtils.CheckIsShowDialogByIdMap
    self.mainChapterExtraDialogCo = cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(sce))
        blocker:RemoveCondition("ShowMainChapterExtraDialog")
        local co = self:ShowFunctionUnlockDialog(unlockType)
        if co then
            cs_coroutine.yield_return(co)
            --- 如果该界面没关闭的话 则等待它关闭
            while CheckIsShowDialogByIdMap({ [Constants.UITypeIds.UICultivatePlayerUpgradeDialog] = true }) do
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(sce))
            end
        end
        if self.isShowTeamRatingDialog then
            cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateLevelUpFinishDialog, parameters = { levelUpType = Constants.UICultivateLevelUpFinishType.TeamRating } }))
        end
        self.isShowTeamRatingDialog = nil
        self.mainChapterExtraDialogCo = nil
    end)

    return self.mainChapterExtraDialogCo
end

