function PlayerComponent:GetRandomMusic(isForce, paramId)
    isForce = checkBool(isForce)
    local selectedCdList = self.playerDojo:GetSelectedAlbumList()
    local musicId = 5400001
    local randomCDId = PlayerInfoUtils.GetDefaultMusicId()
    local isNeedRandom = false
    if checkNumber(self._musicId) == 0 then
        ---未随机过，进行一次随机结果
        isNeedRandom = true
    elseif os.time() - checkNumber(self.randomTime) >= 5 * 60 then
        self.randomTime = os.time()
        ---10分钟
        isNeedRandom = true
    end
    if isNeedRandom then
        if #selectedCdList > 0 then
            local randomIndex = math.random(1, #selectedCdList)
            randomCDId = selectedCdList[randomIndex]
            print('==>>', table.dump(selectedCdList, false, 2))
        end
        local musicVo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", randomCDId)
        if musicVo ~= nil then
            musicId = checkNumber(musicVo.id)
        else
            musicId = randomCDId
        end
        self.randomTime = os.time()
        self._musicId = musicId
    end
    if isForce and paramId then
        self._musicId = checkNumber(paramId)
        self.randomTime = os.time()
    end
    return self._musicId
end

