local ProgressKeyToId = {
    ["cafeMenuEmpty"] = 3001,
    ["cafeCatBall"] = 3013,
    ["cafeCatCar"] = 3004,
    ["climbTower"] = 2015,
}
---更新主界面解锁进度通知
---UpdateProgressInfo
---@param data table 服务器数据   只会发送需要更新的倒计时的key-value
function PlayerComponent:UpdateProgressInfo(data)
    if isNull(self.progressInfo) then
        self.progressInfo = {}
    end
    for i, v in pairs(data) do
        local id = ProgressKeyToId[i]
        if id then
            if checkNumber(v) > 0 then
                self.progressInfo[id] = checkNumber(v) + os.time()
            else
                self.progressInfo[id] = checkNumber(v)
            end
            if id == Constants.SystemToggleIds.Id2015 then
                self:UpdateTowerRewPoint(id)
            end
        end
    end
end

function PlayerComponent:UpdateTowerRewPoint(id)
    local redPointNum = -1
    local info = self.progressInfo[id]
    local isUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id2015)
    if isUnLock then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting6055, "CommonModuleTipsVo", id)
        local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(vo.openType)
        local jumpID = checkInt(row:Get("ID"))
        ---@type OverseaTowerUtils
        local OverseaTowerUtils = import('Game.UI.FightReady.OverseaTower.OverseaTowerUtils')
        local isJumpUnLock = OverseaTowerUtils.IsFunctionUnlock(jumpID, true)
        if isJumpUnLock then
            if info <= 0 and (info - os.time()) <= 0 then
                redPointNum = 0
            else
                redPointNum = info - os.time()
            end
        end
    end
    GameUtils.UpdateServerRedPointData({unQuestTower = redPointNum})
end

function PlayerComponent:GetProgressInfoById(id)
    if self.progressInfo[id] then
        return self.progressInfo[id]
    end
    return nil
end

function PlayerComponent:UpdateProgressRewardInfo(data)
    local rewardData = {}
    for i, v in pairs(data) do
        local id = ProgressKeyToId[i]
        if id then
            rewardData[id] = v
        end
    end
    return rewardData
end
---只要有大于0的  说明是在进行中
function PlayerComponent:IsInProcess()
    for i, v in pairs(self.progressInfo) do
        if v > 0 and (v - os.time()) > 0 then
            return true
        end
    end
    return false
end
---只要有一个小于等于0  都有红点
function PlayerComponent:IsHaveRedPoint()
    for i, v in pairs(self.progressInfo) do
        local isUnLock = GameUtils.IsUnlockedBySystemTogId(i)
        if isUnLock then
            if i == Constants.SystemToggleIds.Id2015 then
                local vo = CfUtils.GetCfVo(AutoIds.IdSetting6055, "CommonModuleTipsVo", i)
                local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(vo.openType)
                local isJumpUnLock = GoodsConfMgr:GetInstance():CheckIsCanJump(row, false)
                if isJumpUnLock then
                    if v <= 0 and (v - os.time()) <= 0 then
                        return true
                    end
                end
            else
                if v <= 0 and (v - os.time()) <= 0 then
                    return true
                end
            end
        end
    end
    return false
end

function PlayerComponent:IsPrivilegeCard()
    return GameUtils.IsHavePrivilegeCard(1)
end
-- 常驻付费签到是否解锁
function PlayerComponent:IsOpenPaidCheckin()
    if type(self:GetPlayerDojo().paidCheckin) == "table" then
        local paidCheckin = self:GetPlayerDojo().paidCheckin
        if table.count(paidCheckin) > 0 then
            if paidCheckin.checkinTime < os.time() then
                return false
            end
            return true
        end
    end
    return false
end

function PlayerComponent:RegGlobalTalentPrivilegeCard()
    ---@type PlayerDojo
    local playerDojo =  self:GetPlayerDojo()
    playerDojo:RegGlobalTalentPrivilegeCard()
   
end

---IsOpenOnlineRewards
---是否开启在线奖励
function PlayerComponent:IsOpenOnlineRewards()
    ---@type PlayerDojo
    local playerDojo  = self:GetPlayerDojo()
    local checkNumber = checkNumber
    local unlockStatus = checkNumber(playerDojo.onlineTaskInfo.unlockStatus)
    if unlockStatus == 0 then
        return false
    end
    local taskList = checkTable(playerDojo.onlineTaskInfo.taskList)
    local allDraw  = true
    local count    = 0
    for i, v in pairs(taskList) do
        if (checkNumber(v.type) == 1 and checkNumber(v.status) ~= 2) or (checkNumber(v.type) == 2 and checkNumber(v.status) <= 1) then
            ---未领取存在的情况下
            allDraw = false
        end
        count = 1
    end
    return unlockStatus == 1 and count > 0 and (not allDraw)
end

function PlayerComponent:IsOpenPlayerEntryWelfare()
    local isOpen = false 
    local playerDojo =  self:GetPlayerDojo()
    if isSet(playerDojo.entryWelfareInfo, "status") then
        local status = checkNumber(playerDojo.entryWelfareInfo.status)
        if status == 1 then
            isOpen = true
        end     
    end 
    return isOpen 
end

function PlayerComponent:IsPopPlayerEntryWelfare()
    local isOpen = false 
    local playerDojo =  self:GetPlayerDojo()
    if isSet(playerDojo.entryWelfareInfo, "status") then
        local status = checkNumber(playerDojo.entryWelfareInfo.status)
        if status == 1 then
            local totalDrawNum = checkInt(playerDojo.entryWelfareInfo.totalDrawNum ) 
            local rewards = playerDojo.entryWelfareInfo.rewards or {}
            local count = #rewards
            if count > 0 and totalDrawNum == count then
                return false
            end
            return true
        end     
    end 
    return isOpen 
end
--- 更新推送状态数据
---@param pushSettings any
function PlayerComponent:UpdatePushSetting(pushSettings)
    -- 旧状态
    local oldBtnStateList = {}
    local json = GameUtils.LoadString("SettingPushBtnStateList")
    if not string.isEmpty(json) then
        oldBtnStateList = table.deserialize(json)
    end

    -- 保存服务器下发的新状态
    local settings = pushSettings
    local json = table.serialize(settings)
    GameUtils.SaveString("SettingPushBtnStateList", json)
    -- print("[推送] 服务器下发推送状态", json)

    -- 新状态
    local newBtnStateList = {}
    if not string.isEmpty(json) then
        newBtnStateList = table.deserialize(json)
    end

    -- 推送总开关是否变化
    local mainId = "main"
    ---@type SDKService
    local SDKService = import('Game.Entry.SDKService')
    local sdkService = SDKService:GetInstance()
    ---@type TpnsSdk
    local TpnsSdk =  sdkService:GetThirdSDK("TpnsSdk")
    if isNotNull(TpnsSdk) then
        if newBtnStateList[mainId] == 0 then
            print("[推送] 更新推送SDK状态 close")
            TpnsSdk:CloseNotice()
        end
    end
end

--- 玩家头像、头像框、徽章，倒计时事件
function PlayerComponent:OnPlayerHeadTimerUpdateHandler_(count, id, elapsed)
    for kind, headDataMap in pairs(self.playerDojo.playerOtherInfo) do
        for headId, headData in pairs(headDataMap) do
            -- 是否有期限的
            if checkInt(headData.expirationTime) > 0 then
                -- 更新剩余秒数
                headData.leftSeconds = headData.expirationTime - GameUtils.GetServerTime()
                -- 处理到期的
                if headData.leftSeconds <= 0 then
                    -- 删除身上的数据
                    headDataMap[headId] = nil
                    -- 如果是正在使用中的头像、头像框，则恢复默认
                    local goodsId  = checkInt(headId)
                    local headKind = checkInt(kind)
                    local nowPhoto = self.playerDojo.playerAvatar
                    local nowFrame = self.playerDojo.playerAvatarFrame
                    if headKind == Constants.PlayerAvatarItemType.Avatar then
                        if checkInt(self.playerDojo.playerAvatar) == goodsId then
                            -- 还原初始头像
                            self.playerDojo.playerAvatar = PlayerInfoUtils.GetDefaultAvatarId(self.playerDojo.gender)
                            GameUtils.Request(Interfaces.Player2DSetAvatarAndFrame, {avatar = self.playerDojo.playerAvatar, avatarFrame = nowFrame}, function(request, response)
                            end)
                        end
                    elseif headKind == Constants.PlayerAvatarItemType.AvatarFrame then
                        if checkInt(self.playerDojo.playerAvatarFrame) == goodsId then
                            -- 还原初始头像框
                            self.playerDojo.playerAvatarFrame = PlayerInfoUtils.GetDefaultAvatarFrameId()
                            GameUtils.Request(Interfaces.Player2DSetAvatarAndFrame, {avatar = nowPhoto, avatarFrame = self.playerDojo.playerAvatarFrame}, function(request, response)
                            end)
                        end
                    elseif headKind == Constants.PlayerAvatarItemType.Paster then
                        -- 删掉徽章
                        self.playerDojo.medals[tostring(goodsId)] = nil
                    end
                    Events.Broadcast(Constants.EventNames.PlayerHeadDateExpired, {goodsId = goodsId, headKind = headKind})
                end
            end
        end
    end
    if Events.HasListener(Constants.EventNames.PlayerHeadLeftTimeCountdown) then
        Events.Broadcast(Constants.EventNames.PlayerHeadLeftTimeCountdown)
    end
    xTry(function()
        ---在线奖励倒计时的逻辑
        local unlockStatus = checkNumber(self.playerDojo.onlineTaskInfo.unlockStatus)
        local taskList = checkTable(self.playerDojo.onlineTaskInfo.taskList)
        if unlockStatus == 1 and #taskList > 0 then
            for i, v in pairs(taskList) do
                v.progress = checkNumber(v.progress) + elapsed
            end
        end
    end)
end


return PlayerComponent
